head.script:
// 전역 변수
scwin.currentMode = "new";
scwin.currentDefectId = "";
scwin.fileManagerRef = null;

/**
 * 페이지 로드 시 초기화 (UnitTest와 동일한 구조)
 */
scwin.onpageload = function () {
    console.log("결함 팝업 로드");

    // 초기화
    scwin.initializeData();
    scwin.getCurrentUserInfo();
    scwin.getProjectIdFromParent();
    scwin.initializeFromParentData();

    // 에디터 초기화
    setTimeout(function () {
        scwin.initializeByMode();
        setTimeout(function () {
            scwin.setEditorContentFromData();
        }, 500);
    }, 300);

    // ⭐ 파일 관련은 FileManager에만 맡기기
    setTimeout(function () {
        // if (scwin.currentMode !== "new") {  // 이 조건문 제거
        console.log("FileManager로 파일 관리 시작");
        scwin.initializeFileManagerWframe();
        // } else {
        //     console.log("신규 등록 모드 - FileManager 숨김");
        //     scwin.hideFileManagerArea();
        // }
    }, 1000);

    console.log("팝업 로드 완료");
};


/**
 * submission 기반 로드를 완전히 제거하고 직접 API 호출만 사용
 */
scwin.sbm_selectFileList_submit = function (e) {
    console.log("=== submission 기반 파일 목록 조회는 사용하지 않음 ===");
    console.log("직접 API 호출 방식을 사용합니다.");

    // 이 함수는 더 이상 사용하지 않음
    return false;
};

scwin.loadDefectFileList = function () {
    var defectId = dmp_defDetail.get("id") || scwin.currentDefectId;

    if (!defectId || scwin.currentMode === "new") {
        console.log("파일 목록 로드 건너뜀");
        return;
    }

    // ⭐ 핵심: submission 직접 호출
    $c.sbm.execute($p, sbm_selectDefFileList);
};
/**
 * FileManager include 로드 완료 콜백
 */
scwin.fileManager_onpageload = function () {
    console.log("FileManager 로드 완료");

    // FileManager 참조 저장 (여러 방법 시도)
    try {
        // 방법 1: getComponentById로 직접 참조
        scwin.fileManagerRef = $p.getComponentById("inc_fileManager");

        if (!scwin.fileManagerRef) {
            console.log("방법 1 실패 - 다른 방법 시도");

            // 방법 2: include된 컴포넌트 찾기
            var includeComponents = document.querySelectorAll('[id="inc_fileManager"]');
            if (includeComponents && includeComponents.length > 0) {
                scwin.fileManagerRef = includeComponents[0];
                console.log("방법 2 성공 - DOM element로 참조");
            }
        }

        if (!scwin.fileManagerRef) {
            console.error("FileManager 참조를 찾을 수 없습니다.");
            return;
        }

        console.log("FileManager 참조 저장 완료:", scwin.fileManagerRef);

        // FileManager 초기화 (지연 시간 추가)
        setTimeout(function () {
            scwin.initializeFileManager();
        }, 500); // 지연 시간 증가

    } catch (e) {
        console.error("FileManager 참조 저장 실패:", e);
    }
};
/**
 * 결함용 FileManager 설정 (수정된 버전)
 */
scwin.configureFileManagerForDefect = function (fileManagerScwin) {
    console.log("=== 결함용 FileManager 설정 시작 ===");

    try {
        // 결함 ID 가져오기
        var defectId = dmp_defDetail.get("id") || scwin.currentDefectId;

        if (!defectId || defectId.trim() === "") {
            console.log("결함 ID가 없어 FileManager 설정을 건너뜁니다.");
            return;
        }

        console.log("결함 ID로 FileManager 설정:", defectId);

        // ⭐ 결함용 설정 (API URL 포함)
        var fileConfig = {
            entityId: defectId,
            entityType: "DEFECT", // 이게 핵심!
            maxFileCount: 10,
            maxFileSize: 10485760,
            apiUrls: {
                fileList: "/InsWebApp/DEF001FileList.pwkjson", // ⭐ 결함 전용 API
                fileDelete: "/InsWebApp/DEF001FileDelete.pwkjson", // ⭐ 결함 전용 API
                fileDownload: "/InsWebApp/FileDownload.pwkjson",
                filePreview: "/InsWebApp/FilePreview.pwkjson",
                imagePreview: "/InsWebApp/ImagePreview.pwkjson"
            }
        };

        console.log("FileManager에 전달할 설정:", fileConfig);

        // FileManager 초기화
        if (fileManagerScwin.initFileManager) {
            fileManagerScwin.initFileManager(fileConfig);
            console.log("FileManager 초기화 완료");
        }

        // 설정 적용
        if (fileManagerScwin.setFileConfig) {
            fileManagerScwin.setFileConfig(fileConfig);
            console.log("FileManager 설정 적용 완료");
        }

        // ⭐ 중요: FileManager가 결함용 API를 사용하도록 강제 설정
        setTimeout(function () {
            console.log("결함 파일 목록 로드 시작:", defectId);

            // FileManager 내부에서 결함용 API 호출
            if (fileManagerScwin.loadFileList) {
                fileManagerScwin.loadFileList(defectId, "DEFECT");
                console.log("결함 파일 목록 로드 요청 완료");
            } else {
                console.error("loadFileList 함수를 찾을 수 없습니다.");

                // 대안: 직접 API 호출
                scwin.loadDefectFilesDirectly(defectId);
            }
        }, 1500); // 충분한 지연 시간

        // FileManager 참조 저장
        scwin.fileManagerScwin = fileManagerScwin;

        console.log("=== 결함용 FileManager 설정 완료 ===");

    } catch (e) {
        console.error("결함용 FileManager 설정 실패:", e);

        // 실패 시 직접 API 호출로 대체
        var defectId = dmp_defDetail.get("id") || scwin.currentDefectId;
        if (defectId) {
            scwin.loadDefectFilesDirectly(defectId);
        }
    }
};

/**
 * 결함 파일 목록 직접 API 호출 (대안 방법)
 */
scwin.loadDefectFilesDirectly = function (defectId) {
    console.log("=== 결함 파일 목록 직접 API 호출 ===", defectId);

    if (!defectId || defectId.trim() === "") {
        console.log("결함 ID가 없습니다.");
        scwin.displayNoFiles();
        return;
    }

    try {
        // ⭐ 결함 전용 API 직접 호출
        var requestData = {
            defVo: {
                id: defectId
            }
        };

        console.log("결함 파일 목록 API 요청:", requestData);

        fetch("/InsWebApp/DEF001FileList.pwkjson", {
            method: "POST",
            headers: {
                "Content-Type": "application/json"
            },
            body: JSON.stringify(requestData)
        })
            .then(function (response) {
                console.log("API 응답 상태:", response.status);
                return response.json();
            })
            .then(function (data) {
                console.log("결함 파일 목록 조회 응답:", data);

                if (data.elHeader && data.elHeader.resSuc) {
                    var fileList = data.elData ? data.elData.attVoList : [];
                    console.log("조회된 결함 파일 목록:", fileList);

                    if (fileList && fileList.length > 0) {
                        scwin.displayDefectFileList(fileList);
                    } else {
                        console.log("이 결함에 첨부된 파일이 없습니다.");
                        scwin.displayNoFiles();
                    }
                } else {
                    var errorMsg = data.elHeader ? data.elHeader.resMsg : "알 수 없는 오류";
                    console.error("결함 파일 목록 조회 실패:", errorMsg);
                    scwin.displayError("파일 목록을 불러올 수 없습니다: " + errorMsg);
                }
            })
            .catch(function (error) {
                console.error("결함 파일 목록 조회 오류:", error);
                scwin.displayError("파일 목록 조회 중 네트워크 오류가 발생했습니다.");
            });

    } catch (e) {
        console.error("결함 파일 목록 직접 로드 실패:", e);
        scwin.displayError("파일 목록 로드 중 오류가 발생했습니다.");
    }
};
/**
 * FileManager wframe 설정 (UnitTestPopup 패턴 적용)
 */
scwin.configureFileManagerWframe = function (fileManagerScwin) {
    console.log("=== 결함용 FileManager 설정 시작 ===");

    try {
        // 결함 ID 가져오기
        var defectId = dmp_defDetail.get("id") || scwin.currentDefectId;

        if (!defectId || defectId.trim() === "") {
            console.log("결함 ID가 없어 FileManager 설정을 건너뜁니다.");
            scwin.showNoFiles();
            return;
        }

        console.log("결함 ID로 FileManager 설정:", defectId);

        // ⭐ 결함용 설정 (UnitTestPopup과 동일한 패턴)
        var fileConfig = {
            entityId: defectId,
            entityType: "DEFECT", // 이게 핵심!
            maxFileCount: 10,
            maxFileSize: 10485760,
            apiUrls: {
                fileList: "/InsWebApp/DEF001FileList.pwkjson", // ⭐ 결함 전용 API
                fileDelete: "/InsWebApp/DEF001FileDelete.pwkjson", // ⭐ 결함 전용 API
                fileDownload: "/InsWebApp/FileDownload.pwkjson",
                filePreview: "/InsWebApp/FilePreview.pwkjson",
                imagePreview: "/InsWebApp/ImagePreview.pwkjson"
            }
        };

        console.log("FileManager에 전달할 설정:", fileConfig);

        // FileManager 초기화
        if (fileManagerScwin.initFileManager) {
            fileManagerScwin.initFileManager(fileConfig);
            console.log("FileManager 초기화 완료");
        }

        // 설정 적용
        if (fileManagerScwin.setFileConfig) {
            fileManagerScwin.setFileConfig(fileConfig);
            console.log("FileManager 설정 적용 완료");
        }

        // ⭐ 파일 목록 로드 (지연 시간 단축)
        setTimeout(function () {
            console.log("결함 파일 목록 로드 시작:", defectId);

            if (fileManagerScwin.loadFileList) {
                fileManagerScwin.loadFileList(defectId, "DEFECT");
                console.log("결함 파일 목록 로드 요청 완료");
            } else {
                console.error("loadFileList 함수를 찾을 수 없습니다.");
                scwin.showSimpleFileList();
            }
        }, 800); // 지연 시간 단축

        // FileManager 참조 저장
        scwin.fileManagerScwin = fileManagerScwin;

        console.log("=== 결함용 FileManager 설정 완료 ===");

    } catch (e) {
        console.error("결함용 FileManager 설정 실패:", e);
        scwin.showSimpleFileList();
    }
};

/**
 * FileManager 초기화
 */
scwin.initializeFileManagerWframe = function () {
    console.log("=== FileManager wframe 초기화 시작 ===");

    try {
        // wframe 컴포넌트 참조 가져오기
        var wframeComponent = $p.getComponentById("inc_fileManager");

        if (!wframeComponent) {
            console.log("wframe 컴포넌트를 찾을 수 없음 - 간단한 파일 목록 사용");
            scwin.showSimpleFileList();
            return;
        }

        console.log("wframe 컴포넌트 발견:", wframeComponent);

        // wframe이 로드될 때까지 대기
        var maxWaitTime = 3000; // 3초로 단축
        var waitInterval = 300; // 0.3초마다 체크
        var elapsedTime = 0;

        var checkWframeLoaded = setInterval(function () {
            elapsedTime += waitInterval;

            try {
                // wframe 내부 window 접근 시도
                var wframeWindow = wframeComponent.getWindow();

                if (wframeWindow && wframeWindow.scwin) {
                    console.log("wframe 내부 스크립트 접근 성공");
                    clearInterval(checkWframeLoaded);

                    // FileManager 설정 적용
                    scwin.configureFileManagerWframe(wframeWindow.scwin);

                } else if (elapsedTime >= maxWaitTime) {
                    console.log("wframe 로드 시간 초과 - 간단한 파일 목록 사용");
                    clearInterval(checkWframeLoaded);
                    scwin.showSimpleFileList();

                } else {
                    console.log("wframe 로드 대기 중... (" + elapsedTime + "ms)");
                }

            } catch (e) {
                if (elapsedTime >= maxWaitTime) {
                    console.log("wframe 접근 실패 - 간단한 파일 목록 사용");
                    clearInterval(checkWframeLoaded);
                    scwin.showSimpleFileList();
                } else {
                    console.log("wframe 접근 시도 중... (" + elapsedTime + "ms)");
                }
            }
        }, waitInterval);

    } catch (e) {
        console.error("FileManager wframe 초기화 실패:", e);
        scwin.showSimpleFileList();
    }
};

/**
 * 에디터 내용을 데이터맵에서 설정
 */
scwin.setEditorContentFromData = function () {
    console.log("=== 에디터 내용 설정 시작 ===");

    try {
        // 데이터맵 전체 내용 확인
        var allData = dmp_defDetail.getJSON();
        console.log("데이터맵 전체 내용:", allData);

        var description = dmp_defDetail.get("description") || "";
        var remarks = dmp_defDetail.get("remarks") || "";

        console.log("데이터맵에서 가져온 원본 내용:");
        console.log("- description type:", typeof description);
        console.log("- description length:", description ? description.length : 0);
        console.log("- description preview:", description ? description.substring(0, 100) : "null/undefined");
        console.log("- remarks type:", typeof remarks);
        console.log("- remarks length:", remarks ? remarks.length : 0);
        console.log("- remarks preview:", remarks ? remarks.substring(0, 100) : "null/undefined");

        // 에디터가 준비될 때까지 반복 확인
        var maxAttempts = 15;
        var attempts = 0;

        var setContentInterval = setInterval(function () {
            attempts++;
            console.log("에디터 설정 시도:", attempts);

            try {
                var descEditorReady = false;
                var remarksEditorReady = false;

                // description 에디터 확인 및 설정
                if (typeof editor_description !== 'undefined' && editor_description) {
                    console.log("description 에디터 발견");

                    if (editor_description.setHTML && editor_description.getHTML) {
                        console.log("description 에디터 메서드 확인됨");

                        var descContent = description;

                        // HTML 엔티티 디코딩
                        if (descContent && (descContent.includes('&lt;') || descContent.includes('&gt;') || descContent.includes('&quot;'))) {
                            var originalDesc = descContent;
                            descContent = scwin.fullyDecodeHtml(descContent);
                            console.log("description HTML 디코딩:", originalDesc.substring(0, 50), "→", descContent.substring(0, 50));
                        }

                        // 빈 내용 처리
                        if (!descContent || descContent.trim() === "" || descContent === "<p></p>" || descContent === "<br>") {
                            if (scwin.currentMode === "new") {
                                descContent = "";
                            } else {
                                descContent = "<p style='color: #999; font-style: italic;'>결함 설명이 없습니다.</p>";
                            }
                            console.log("description 빈 내용 처리 완료");
                        }

                        try {
                            editor_description.setHTML(descContent);
                            console.log("description 에디터 설정 완료 - 길이:", descContent.length);
                            descEditorReady = true;
                        } catch (setError) {
                            console.log("description 에디터 setHTML 실패:", setError);
                        }
                    } else {
                        console.log("description 에디터 메서드 아직 준비 안됨");
                    }
                } else {
                    console.log("description 에디터가 아직 준비되지 않음");
                }

                // remarks 에디터 확인 및 설정
                if (typeof editor_remarks !== 'undefined' && editor_remarks) {
                    console.log("remarks 에디터 발견");

                    if (editor_remarks.setHTML && editor_remarks.getHTML) {
                        console.log("remarks 에디터 메서드 확인됨");

                        var remarksContent = remarks;

                        // HTML 엔티티 디코딩
                        if (remarksContent && (remarksContent.includes('&lt;') || remarksContent.includes('&gt;') || remarksContent.includes('&quot;'))) {
                            var originalRemarks = remarksContent;
                            remarksContent = scwin.fullyDecodeHtml(remarksContent);
                            console.log("remarks HTML 디코딩:", originalRemarks.substring(0, 50), "→", remarksContent.substring(0, 50));
                        }

                        // 빈 내용 처리
                        if (!remarksContent || remarksContent.trim() === "" || remarksContent === "<p></p>" || remarksContent === "<br>") {
                            if (scwin.currentMode === "new") {
                                remarksContent = "";
                            } else {
                                remarksContent = "<p style='color: #999; font-style: italic;'>비고사항이 없습니다.</p>";
                            }
                            console.log("remarks 빈 내용 처리 완료");
                        }

                        try {
                            editor_remarks.setHTML(remarksContent);
                            console.log("remarks 에디터 설정 완료 - 길이:", remarksContent.length);
                            remarksEditorReady = true;
                        } catch (setError) {
                            console.log("remarks 에디터 setHTML 실패:", setError);
                        }
                    } else {
                        console.log("remarks 에디터 메서드 아직 준비 안됨");
                    }
                } else {
                    console.log("remarks 에디터가 아직 준비되지 않음");
                }

                // 모든 에디터 설정 완료 확인
                if (descEditorReady && remarksEditorReady) {
                    clearInterval(setContentInterval);
                    console.log("=== 모든 에디터 내용 설정 완료 ===");

                    // 에디터 모드 설정
                    setTimeout(function () {
                        scwin.setEditorMode(scwin.currentMode === "edit" || scwin.currentMode === "new");
                    }, 100);

                    return;
                }

            } catch (e) {
                console.log("에디터 설정 시도 중 오류:", e);
                if (attempts >= maxAttempts) {
                    clearInterval(setContentInterval);
                    console.error("에디터 설정 최대 시도 횟수 초과");
                }
            }

            if (attempts >= maxAttempts) {
                clearInterval(setContentInterval);
                console.error("에디터 설정 시간 초과");
            }
        }, 200);

    } catch (e) {
        console.error("에디터 내용 설정 실패:", e);
    }
};

/**
 * DefectPopup.xml용 데이터 초기화 (UnitTestPopup과 동일한 구조)
 */
scwin.initializeData = function () {
    console.log("결함 팝업 데이터 초기화 시작");

    // 전역 변수 초기화
    scwin.CURRENT_PROJECT_ID = "";
    scwin.CURRENT_USER_ID = "";
    scwin.CURRENT_USER_GROUP_ID = "";
    scwin.currentMode = "new"; // new, edit, view
    scwin.currentDefectId = "";

    // 데이터맵 초기화
    try {
        dmp_defDetail.setEmptyValue();

        // 결함 기본값 설정
        dmp_defDetail.set("status", "대기");
        dmp_defDetail.set("priority", "보통");
        dmp_defDetail.set("isDeleted", "N");

        console.log("결함 데이터맵 초기화 완료");
    } catch (e) {
        console.error("데이터맵 초기화 중 오류:", e);
    }

    console.log("결함 팝업 데이터 초기화 완료");
};

/**
 * 사용자 정보 가져오기 (UnitTest와 동일)
 */
scwin.getCurrentUserInfo = function () {
    try {
        var parentWindow = $p.getParentWindow();
        if (parentWindow) {
            var headerFrame = parentWindow.$p.getComponentById("pg_header");
            if (headerFrame && headerFrame.getWindow && headerFrame.getWindow().scwin) {
                var headerScwin = headerFrame.getWindow().scwin;

                scwin.CURRENT_USER_ID = headerScwin.USER_ID || "1";
                scwin.CURRENT_USER_NAME = headerScwin.USER_NAME || "사용자";

                // 프로젝트 정보
                if (parentWindow.scwin && parentWindow.scwin.SEL_PJT_ID) {
                    scwin.CURRENT_PROJECT_ID = parentWindow.scwin.SEL_PJT_ID;
                }

                console.log("헤더에서 가져온 사용자 정보:");
                console.log("- USER_ID:", scwin.CURRENT_USER_ID);
                console.log("- USER_NAME:", scwin.CURRENT_USER_NAME);
                console.log("- PROJECT_ID:", scwin.CURRENT_PROJECT_ID);

                return true;
            }
        }

        // 기본값 설정
        scwin.CURRENT_USER_ID = "1";
        scwin.CURRENT_USER_NAME = "사용자";
        scwin.CURRENT_PROJECT_ID = "";
        console.log("기본값으로 사용자 정보 설정");
        return false;

    } catch (e) {
        console.error("사용자 정보 가져오기 실패:", e);
        scwin.CURRENT_USER_ID = "1";
        scwin.CURRENT_USER_NAME = "사용자";
        scwin.CURRENT_PROJECT_ID = "";
        return false;
    }
};

/**
 * 부모창에서 전달받은 데이터 처리 (단위테스트 방식 적용)
 */
scwin.initializeFromParentData = function () {
    try {
        console.log("=== 결함 팝업 데이터 초기화 시작 ===");

        var paramData = $p.getParameter();
        console.log("팝업 파라미터 전체:", paramData);

        if (!paramData) {
            console.log("getParameter()가 undefined, 대안 방법들 시도");

            var parent = $p.getParentWindow();
            if (parent && parent.tempPopupData) {
                paramData = parent.tempPopupData;
                console.log("parent.tempPopupData에서 가져온 데이터:", paramData);
            } else if (window.tempPopupData) {
                paramData = window.tempPopupData;
                console.log("window.tempPopupData에서 가져온 데이터:", paramData);
            }
        }

        if (paramData && paramData.defectData) {
            var defectInfo = paramData.defectData;
            console.log("전달받은 defectInfo:", defectInfo);

            scwin.currentMode = defectInfo.mode || "view";
            scwin.CURRENT_PROJECT_ID = defectInfo.pjtId || "";
            scwin.CURRENT_USER_ID = defectInfo.currentUserId || "1";

            // ⭐ 핵심 수정: 실제 결함 데이터는 defectInfo.defectData에 있음
            if (defectInfo.defectData) {
                console.log("실제 결함 데이터 설정:", defectInfo.defectData);
                dmp_defDetail.setJSON(defectInfo.defectData);
                scwin.currentDefectId = defectInfo.defectData.id || "";
            }
            // ⭐ 추가: defectInfo 자체가 결함 데이터인 경우도 처리
            else if (defectInfo.id) {
                console.log("defectInfo 자체가 결함 데이터:", defectInfo);
                // mode, pjtId 등 메타데이터 제외하고 결함 데이터만 추출
                var actualDefectData = {};
                var metaFields = ['mode', 'pjtId', 'currentUserId', 'currentUserName'];

                for (var key in defectInfo) {
                    if (metaFields.indexOf(key) === -1) {
                        actualDefectData[key] = defectInfo[key];
                    }
                }

                console.log("추출된 실제 결함 데이터:", actualDefectData);
                dmp_defDetail.setJSON(actualDefectData);
                scwin.currentDefectId = actualDefectData.id || "";
            }
        }

        console.log("최종 설정된 값들:");
        console.log("현재 모드:", scwin.currentMode);
        console.log("프로젝트 ID:", scwin.CURRENT_PROJECT_ID);
        console.log("사용자 ID:", scwin.CURRENT_USER_ID);
        console.log("결함 ID:", scwin.currentDefectId);
        console.log("데이터맵 내용:", dmp_defDetail.getJSON());

        // 임시 데이터 정리
        try {
            if (window.tempPopupData) {
                delete window.tempPopupData;
            }
            var parent = $p.getParentWindow();
            if (parent && parent.tempPopupData) {
                delete parent.tempPopupData;
            }
        } catch (e) {
            console.log("임시 데이터 정리 실패:", e);
        }

        console.log("=== 결함 팝업 데이터 초기화 완료 ===");

    } catch (e) {
        console.error("부모창 데이터 처리 실패:", e);
        scwin.currentMode = "new";

        // 실패 시 기본값 설정
        dmp_defDetail.set("status", "대기");
        dmp_defDetail.set("priority", "보통");
        dmp_defDetail.set("isDeleted", "N");
    }
};
/**
 * 모드에 따른 초기화 (단위테스트 방식 적용)
 */
scwin.initializeByMode = function () {
    console.log("=== 모드별 초기화:", scwin.currentMode, "===");

    // 모드별 설정
    switch (scwin.currentMode) {
        case "new":
            scwin.initializeNewMode();
            break;
        case "edit":
            scwin.initializeEditMode();
            break;
        case "view":
            scwin.initializeViewMode();
            break;
        default:
            scwin.initializeNewMode();
    }

    // 팝업 제목 설정
    scwin.setPopupTitle();

    console.log("=== 모드별 초기화 완료 ===");
};

/**
 * 팝업 제목 설정
 */
scwin.setPopupTitle = function () {
    try {
        var title = "";
        switch (scwin.currentMode) {
            case "new":
                title = "새 결함 등록";
                break;
            case "edit":
                title = "결함 수정";
                break;
            case "view":
                title = "결함 상세보기";
                break;
            default:
                title = "결함 관리";
        }

        var titleComponent = $p.getComponentById("spn_popupTitle");
        if (titleComponent && titleComponent.setValue) {
            titleComponent.setValue(title);
            console.log("팝업 제목 설정:", title);
        }

    } catch (e) {
        console.log("제목 설정 실패:", e);
    }
};

/**
 * 등록 모드 초기화
 */
scwin.initializeNewMode = function () {
    console.log("등록 모드 초기화 (wframe)");

    // 기본값이 설정되지 않은 경우에만 설정
    if (!dmp_defDetail.get("status")) {
        dmp_defDetail.set("status", "NEW");
