/**
 * 부모 창에서 프로젝트 ID 가져오기 (UnitTestPopup과 동일)
 */
scwin.getProjectIdFromParent = function () {
    try {
        var parentWindow = $p.getParentWindow();
        if (parentWindow && parentWindow.scwin && parentWindow.scwin.SEL_PJT_ID) {
            scwin.CURRENT_PROJECT_ID = parentWindow.scwin.SEL_PJT_ID;
            console.log("현재 선택된 프로젝트 ID: " + scwin.CURRENT_PROJECT_ID);
        } else {
            console.log("부모 창에서 프로젝트 ID를 찾을 수 없습니다.");
        }
    } catch (e) {
        console.error("부모 창에서 프로젝트 ID 가져오기 실패:", e);
    }
};

/**
 * 폼 모드 설정
 */
scwin.setFormMode = function (mode) {
    console.log("폼 모드 전환:", mode);

    try {
        if (mode === "edit" || mode === "new") {
            // 편집 모드
            scwin.setFieldsReadOnly(false);
            scwin.setEditorMode(true);
            scwin.setFileManagerMode(true);

            // 버튼 상태 변경
            if (typeof btn_save !== 'undefined' && btn_save.show) {
                btn_save.show();
            }
            if (typeof btn_edit !== 'undefined' && btn_edit.hide) {
                btn_edit.hide();
            }

            if (mode === "new") {
                if (typeof btn_delete !== 'undefined' && btn_delete.hide) {
                    btn_delete.hide();
                }
            } else {
                if (typeof btn_delete !== 'undefined' && btn_delete.show) {
                    btn_delete.show();
                }
            }

        } else if (mode === "view") {
            // 조회 모드
            scwin.setFieldsReadOnly(true);
            scwin.setEditorMode(false);
            scwin.setFileManagerMode(false);

            // 버튼 상태 변경
            if (typeof btn_save !== 'undefined' && btn_save.hide) {
                btn_save.hide();
            }
            if (typeof btn_edit !== 'undefined' && btn_edit.show) {
                btn_edit.show();
            }
            if (typeof btn_delete !== 'undefined' && btn_delete.show) {
                btn_delete.show();
            }
        }

        console.log("폼 모드 전환 완료:", mode);

    } catch (e) {
        console.error("setFormMode 오류:", e);
    }
};

/**
 * FileManager 모드 설정
 */
scwin.setFileManagerMode = function (isEditMode) {
    console.log("FileManager 모드 설정 (wframe):", isEditMode ? "편집" : "조회");

    try {
        if (scwin.fileManagerScwin) {
            console.log("FileManager 스크립트 참조 있음 - 모드 설정 가능");

            // FileManager 내부 설정이 있다면 적용
            if (scwin.fileManagerScwin.setEditMode) {
                scwin.fileManagerScwin.setEditMode(isEditMode);
            }

            // 또는 FileManager 내부 UI 직접 조작
            if (scwin.fileManagerWframe) {
                var wframeWindow = scwin.fileManagerWframe.getWindow();
                if (wframeWindow && wframeWindow.document) {
                    var uploadArea = wframeWindow.document.getElementById("grp_fileUploadArea");
                    if (uploadArea) {
                        uploadArea.style.display = isEditMode ? "block" : "none";
                    }
                }
            }

        } else {
            console.log("FileManager 스크립트 참조 없음 - 모드 설정 불가");
        }

        console.log("FileManager 모드 설정 완료");

    } catch (e) {
        console.error("FileManager 모드 설정 실패:", e);
    }
};

/**
 * 필드 읽기 전용 설정
 */
scwin.setFieldsReadOnly = function (readOnly) {
    try {
        var editableFields = ["inp_name", "sel_priority", "sel_status", "cal_fixDueDate", "inp_assigneeName"];

        editableFields.forEach(function (fieldId) {
            var field = $p.getComponentById(fieldId);
            if (field && field.setReadOnly) {
                field.setReadOnly(readOnly);
            }
        });

        console.log("필드 읽기 전용 설정:", readOnly);

    } catch (e) {
        console.error("필드 읽기 전용 설정 오류:", e);
    }
};

/**
 * 에디터 모드 설정 (UnitTestPopup과 동일)
 */
scwin.setEditorMode = function (isEditMode) {
    console.log("=== 에디터 모드 전환:", isEditMode ? "편집" : "조회", "===");

    try {
        // description 에디터 설정
        if (typeof editor_description !== 'undefined' && editor_description) {
            if (editor_description.setReadOnly) {
                editor_description.setReadOnly(!isEditMode);
                console.log("description 에디터 읽기전용 설정:", !isEditMode);
            }

            // 에디터 스타일 조정
            if (isEditMode) {
                editor_description.setStyle("border: 2px solid #98BED6; background-color: white;");
            } else {
                editor_description.setStyle("border: 1px solid #ddd; background-color: #f8f9fa;");
            }
        } else {
            console.warn("description 에디터를 찾을 수 없음");
        }

        // remarks 에디터 설정
        if (typeof editor_remarks !== 'undefined' && editor_remarks) {
            if (editor_remarks.setReadOnly) {
                editor_remarks.setReadOnly(!isEditMode);
                console.log("remarks 에디터 읽기전용 설정:", !isEditMode);
            }

            // 에디터 스타일 조정
            if (isEditMode) {
                editor_remarks.setStyle("border: 2px solid #98BED6; background-color: white;");
            } else {
                editor_remarks.setStyle("border: 1px solid #ddd; background-color: #f8f9fa;");
            }
        } else {
            console.warn("remarks 에디터를 찾을 수 없음");
        }

        // 조회 모드일 때 내용 업데이트
        if (!isEditMode) {
            setTimeout(function () {
                scwin.updateViewContent();
            }, 100);
        }

        console.log("=== 에디터 모드 설정 완료 ===");

    } catch (e) {
        console.error("에디터 읽기전용 설정 실패:", e);
    }
};

/**
 * 조회 모드 내용 업데이트
 */
scwin.updateViewContent = function () {
    console.log("=== 조회 모드 내용 업데이트 ===");

    try {
        var description = dmp_defDetail.get("description") || "";
        var remarks = dmp_defDetail.get("remarks") || "";

        console.log("업데이트할 내용:");
        console.log("- description:", description ? "있음 (" + description.length + "자)" : "없음");
        console.log("- remarks:", remarks ? "있음 (" + remarks.length + "자)" : "없음");

        // description 에디터 업데이트
        if (typeof editor_description !== 'undefined' && editor_description && editor_description.setHTML) {
            var descContent = description;
            if (descContent && (descContent.includes('&lt;') || descContent.includes('&gt;') || descContent.includes('&quot;'))) {
                descContent = scwin.fullyDecodeHtml(descContent);
            }
            if (!descContent || descContent.trim() === "") {
                descContent = "<p style='color: #999; font-style: italic;'>결함 설명이 없습니다.</p>";
            }
            editor_description.setHTML(descContent);
            console.log("description 에디터 업데이트 완료");
        }

        // remarks 에디터 업데이트
        if (typeof editor_remarks !== 'undefined' && editor_remarks && editor_remarks.setHTML) {
            var remarksContent = remarks;
            if (remarksContent && (remarksContent.includes('&lt;') || remarksContent.includes('&gt;') || remarksContent.includes('&quot;'))) {
                remarksContent = scwin.fullyDecodeHtml(remarksContent);
            }
            if (!remarksContent || remarksContent.trim() === "") {
                remarksContent = "<p style='color: #999; font-style: italic;'>비고사항이 없습니다.</p>";
            }
            editor_remarks.setHTML(remarksContent);
            console.log("remarks 에디터 업데이트 완료");
        }

        console.log("=== 조회 모드 내용 업데이트 완료 ===");

    } catch (e) {
        console.error("내용 업데이트 실패:", e);
    }
};

/**
 * 저장 버튼 클릭
 */
scwin.btn_save_onclick = function(e) {
    console.log("=== 저장 버튼 클릭 ===");

    // 에디터 내용을 먼저 데이터맵에 저장
    try {
        console.log("에디터 내용 데이터맵에 저장 시작");

        if (typeof editor_description !== 'undefined' && editor_description && editor_description.getHTML) {
            var descriptionHTML = editor_description.getHTML();
            console.log("결함 설명 에디터 내용 길이:", descriptionHTML ? descriptionHTML.length : 0);

            var cleanDesc = descriptionHTML.replace(/<[^>]*>/g, '').trim();
            if (cleanDesc === "") {
                console.log("결함 설명이 비어있음");
                dmp_defDetail.set("description", "");
            } else {
                dmp_defDetail.set("description", descriptionHTML);
                console.log("결함 설명 저장 완료");
            }
        }

        if (typeof editor_remarks !== 'undefined' && editor_remarks && editor_remarks.getHTML) {
            var remarksHTML = editor_remarks.getHTML();
            console.log("비고사항 에디터 내용 길이:", remarksHTML ? remarksHTML.length : 0);

            var cleanRemarks = remarksHTML.replace(/<[^>]*>/g, '').trim();
            if (cleanRemarks === "") {
                console.log("비고사항이 비어있음");
                dmp_defDetail.set("remarks", "");
            } else {
                dmp_defDetail.set("remarks", remarksHTML);
                console.log("비고사항 저장 완료");
            }
        }

    } catch(e) {
        console.error("에디터 내용 저장 실패:", e);
    }

    // 유효성 검사
    if (!scwin.validateForm()) {
        return;
    }

    // ⭐ 변수 선언을 console.log 보다 먼저 해야 함
    var fixDueDate = dmp_defDetail.get("fixDueDate");
    var fixedDate = dmp_defDetail.get("fixedDate");

    console.log("날짜 필드 처리 전:");
    console.log("- fixDueDate:", fixDueDate, "type:", typeof fixDueDate);
    console.log("- fixedDate:", fixedDate, "type:", typeof fixedDate);

    // 빈 문자열이나 null인 경우 null로 설정
    if (!fixDueDate || fixDueDate.trim() === "") {
        dmp_defDetail.set("fixDueDate", null);
        console.log("fixDueDate를 null로 설정");
    } else {
        // 날짜 형식 변환 (YYYYMMDD -> YYYY-MM-DD)
        if (fixDueDate.length === 8) {
            var formattedDate = fixDueDate.substring(0,4) + "-" + fixDueDate.substring(4,6) + "-" + fixDueDate.substring(6,8);
            dmp_defDetail.set("fixDueDate", formattedDate);
            console.log("fixDueDate 형식 변환:", fixDueDate, "->", formattedDate);
        }
    }

    if (!fixedDate || fixedDate.trim() === "") {
        dmp_defDetail.set("fixedDate", null);
        console.log("fixedDate를 null로 설정");
    } else {
        // 날짜 형식 변환
        if (fixedDate.length === 8) {
            var formattedDate = fixedDate.substring(0,4) + "-" + fixedDate.substring(4,6) + "-" + fixedDate.substring(6,8);
            dmp_defDetail.set("fixedDate", formattedDate);
            console.log("fixedDate 형식 변환:", fixedDate, "->", formattedDate);
        }
    }

    console.log("날짜 필드 처리 후:");
    console.log("- fixDueDate:", dmp_defDetail.get("fixDueDate"));
    console.log("- fixedDate:", dmp_defDetail.get("fixedDate"));

    // 현재 시간 설정
    var currentTime = new Date().toISOString();
    console.log("현재 시간 설정:", currentTime);

    // 상태 코드 변환 (한글 → 영문)
    var statusMapping = {
        "대기": "NEW",
        "진행중": "IPR", 
        "완료": "COM"
    };

    var priorityMapping = {
        "높음": "HI",
        "보통": "MD",
        "낮음": "LO"
    };

    var currentStatus = dmp_defDetail.get("status");
    var currentPriority = dmp_defDetail.get("priority");

    // 상태 코드 변환
    if (statusMapping[currentStatus]) {
        dmp_defDetail.set("status", statusMapping[currentStatus]);
    }

    // 우선순위 코드 변환  
    if (priorityMapping[currentPriority]) {
        dmp_defDetail.set("priority", priorityMapping[currentPriority]);
    }

    try {
        if (scwin.currentMode === "new") {
            console.log("등록 모드 - 새 결함 등록");

            // 등록일시와 수정일시 설정
            dmp_defDetail.set("createdAt", currentTime);
            dmp_defDetail.set("updatedAt", currentTime);

            // 등록자 정보 설정
            if (scwin.CURRENT_USER_ID) {
                dmp_defDetail.set("assignee", scwin.CURRENT_USER_ID);
            }

            // 프로젝트 ID 설정
            if (scwin.CURRENT_PROJECT_ID) {
                dmp_defDetail.set("pjtId", scwin.CURRENT_PROJECT_ID);
            } else {
                console.error("프로젝트 ID가 없습니다!");
                $c.win.alert("프로젝트 ID가 설정되지 않았습니다. 페이지를 새로고침해주세요.");
                return;
            }

            // 삭제 여부 기본값
            dmp_defDetail.set("isDeleted", "N");

            console.log("등록 전 최종 데이터:", dmp_defDetail.getJSON());
            $c.sbm.execute($p, sbm_insertDef);

        } else if (scwin.currentMode === "edit") {
            console.log("수정 모드 - 기존 결함 수정");

            // ID 체크
            if (!dmp_defDetail.get("id")) {
                console.error("수정할 결함 ID가 없습니다!");
                $c.win.alert("수정할 결함 ID가 없습니다.");
                return;
            }

            // 수정일시만 업데이트
            dmp_defDetail.set("updatedAt", currentTime);

            console.log("수정 전 최종 데이터:", dmp_defDetail.getJSON());
            $c.sbm.execute($p, sbm_updateDef);

        } else {
            console.warn("알 수 없는 모드:", scwin.currentMode);
            $c.win.alert("저장할 수 없는 상태입니다. 페이지를 새로고침해주세요.");
        }

    } catch (saveError) {
        console.error("저장 처리 중 오류:", saveError);
        $c.win.alert("저장 중 오류가 발생했습니다: " + saveError.message);
    }
};


/**
 * 폼 유효성 검사
 */
scwin.validateForm = function () {
    console.log("폼 유효성 검사 시작");

    try {
        var name = dmp_defDetail.get("name");
        var description = dmp_defDetail.get("description");
        var priority = dmp_defDetail.get("priority");
        var status = dmp_defDetail.get("status");

        console.log("유효성 검사 데이터:");
        console.log("- name:", name);
        console.log("- description:", description ? "있음" : "없음");
        console.log("- priority:", priority);
        console.log("- status:", status);

        // 필수 필드 검사
        if (!name || name.trim() === "") {
            console.log("결함명 누락");
            $c.win.alert("결함명을 입력해주세요.");

            try {
                var nameField = $p.getComponentById("inp_name");
                if (nameField && nameField.focus) {
                    nameField.focus();
                }
            } catch (e) {
                console.log("결함명 필드 포커스 실패:", e);
            }
            return false;
        }

        if (!description || description.trim() === "" || description === "<p></p>" || description === "<p><br></p>") {
            console.log("결함 설명 누락");
            $c.win.alert("결함 설명을 입력해주세요.");

            try {
                if (typeof editor_description !== 'undefined' && editor_description && editor_description.focus) {
                    editor_description.focus();
                }
            } catch (e) {
                console.log("에디터 포커스 실패:", e);
            }
            return false;
        }

        if (!priority || priority.trim() === "") {
            console.log("우선순위 누락");
            $c.win.alert("우선순위를 선택해주세요.");
            return false;
        }

        if (!status || status.trim() === "") {
            console.log("상태 누락");
            $c.win.alert("상태를 선택해주세요.");
            return false;
        }

        // 프로젝트 ID 체크
        if (!scwin.CURRENT_PROJECT_ID || scwin.CURRENT_PROJECT_ID.trim() === "") {
            console.log("프로젝트 ID 누락");
            $c.win.alert("프로젝트가 선택되지 않았습니다. 페이지를 새로고침해주세요.");
            return false;
        }

        console.log("폼 유효성 검사 통과");
        return true;

    } catch (validationError) {
        console.error("유효성 검사 중 오류:", validationError);
        $c.win.alert("유효성 검사 중 오류가 발생했습니다.");
        return false;
    }
};

/**
 * 등록 완료
 */
scwin.sbm_insertDef_submitdone = function(e) {
    console.log("결함 등록 완료 응답:", e);

    try {
        var responseData = e.responseJSON;
        console.log("응답 JSON:", responseData);

        var elHeader = responseData ? responseData.elHeader : null;
        var elData = responseData ? responseData.elData : null;

        console.log("elHeader:", elHeader);
        console.log("elData:", elData);

        if (!elHeader || elHeader.resSuc == false) {
            var errorMsg = "등록에 실패했습니다.";
            if (elHeader && elHeader.resMsg) {
                errorMsg += "\n오류메시지: " + elHeader.resMsg;
            }
            if (elHeader && elHeader.resCode) {
                errorMsg += "\n오류코드: " + elHeader.resCode;
            }
            console.error("등록 실패:", errorMsg);
            $c.win.alert(errorMsg);
            return;
        }

        // ⭐ 서버에서 생성된 결함 ID 확인
        if (elData && elData.defectId) {
            scwin.currentDefectId = elData.defectId;
            dmp_defDetail.set("id", elData.defectId);
            console.log("서버에서 생성된 결함 ID:", elData.defectId);
        } else {
            console.warn("서버 응답에 결함 ID가 없습니다.");
        }

        console.log("결함 등록 성공");
        $c.win.alert("등록되었습니다.");

        // 등록 성공 후 팝업 닫기
        scwin.closeDefectPopup();

    } catch (error) {
        console.error("등록 응답 처리 중 오류:", error);
        $c.win.alert("등록 처리 중 오류가 발생했습니다.");
    }
};
