/**
 * 결함 데이터 초기화
 */
scwin.initializeDefectData = function () {
    dmp_defDetail.setEmptyValue();

    // 기본값 설정
    dmp_defDetail.set("status", "대기");
    dmp_defDetail.set("priority", "보통");
    dmp_defDetail.set("isDeleted", "N");

    // FileManager 초기화
    scwin.clearFileManager();

    console.log("결함 데이터 초기화 완료");
};

/**
 * FileManager 엔티티 ID 업데이트
 */
scwin.updateFileManagerEntity = function (entityId) {
    console.log("FileManager 엔티티 ID 업데이트 (wframe):", entityId);

    try {
        if (scwin.fileManagerScwin && scwin.fileManagerScwin.setFileConfig) {
            // 기존 설정을 유지하면서 entityId만 업데이트
            var updatedConfig = {
                entityId: entityId
            };

            scwin.fileManagerScwin.setFileConfig(updatedConfig);

            // 설정 후 파일 목록 로드
            setTimeout(function () {
                console.log("엔티티 ID 업데이트 후 파일 목록 로드:", entityId);
                if (scwin.fileManagerScwin.loadFileList) {
                    scwin.fileManagerScwin.loadFileList(entityId, "defect");
                }
            }, 200);

            console.log("FileManager 엔티티 ID 업데이트 완료");
        } else {
            console.log("FileManager 참조가 없음 - wframe 재초기화 후 엔티티 ID 설정");

            // wframe 재초기화 후 엔티티 ID 설정
            setTimeout(function () {
                scwin.initializeFileManagerWframe();

                // 초기화 완료 후 엔티티 ID 다시 설정
                setTimeout(function () {
                    if (scwin.fileManagerScwin) {
                        scwin.updateFileManagerEntity(entityId);
                    } else {
                        console.log("wframe 재초기화 실패 - 간단한 파일 목록 사용");
                        scwin.showSimpleFileList();
                    }
                }, 2000);
            }, 500);
        }
    } catch (e) {
        console.error("FileManager 엔티티 ID 업데이트 실패:", e);
        scwin.showSimpleFileList();
    }
};



/**
 * FileManager 새로고침
 */
scwin.refreshFileManager = function () {
    console.log("FileManager 새로고침 (wframe)");

    try {
        if (scwin.fileManagerScwin && scwin.fileManagerScwin.loadFileList) {
            var entityId = dmp_defDetail.get("id");
            if (entityId && entityId.trim() !== "") {
                console.log("FileManager 파일 목록 새로고침:", entityId);
                scwin.fileManagerScwin.loadFileList(entityId, "defect");
            } else {
                console.log("결함 ID가 없어 파일 목록 새로고침을 건너뜀");
            }
        } else {
            console.log("FileManager 참조가 없음 - wframe 재초기화 시도");

            // wframe 재초기화 시도 (한 번만)
            if (!scwin.wframeReinitAttempted) {
                scwin.wframeReinitAttempted = true;
                setTimeout(function () {
                    scwin.initializeFileManagerWframe();
                }, 1000);
            } else {
                console.log("wframe 재초기화 이미 시도함 - 간단한 파일 목록 사용");
                scwin.showSimpleFileList();
            }
        }
    } catch (e) {
        console.error("FileManager 새로고침 실패:", e);
        scwin.showSimpleFileList();
    }
};


/**
 * FileManager 초기화
 */
scwin.clearFileManager = function () {
    console.log("FileManager 초기화");

    try {
        if (scwin.fileManagerRef && scwin.fileManagerRef.getWindow) {
            var fileManagerWindow = scwin.fileManagerRef.getWindow();
            var fileManagerScwin = fileManagerWindow.scwin;

            if (fileManagerScwin && fileManagerScwin.clearFiles) {
                fileManagerScwin.clearFiles();
            }
        }
    } catch (e) {
        console.error("FileManager 초기화 실패:", e);
    }
};

/**
 * HTML 엔티티 완전 디코딩
 */
scwin.fullyDecodeHtml = function (str) {
    if (!str) return str;

    var result = str;
    var attempts = 0;
    var maxAttempts = 5;

    while (attempts < maxAttempts && (result.includes('&lt;') || result.includes('&gt;') || result.includes('&quot;'))) {
        attempts++;
        var previousResult = result;

        result = result
            .replace(/&lt;/g, '<')
            .replace(/&gt;/g, '>')
            .replace(/&quot;/g, '"')
            .replace(/&#39;/g, "'")
            .replace(/&apos;/g, "'")
            .replace(/&nbsp;/g, ' ')
            .replace(/&amp;/g, '&');

        if (result === previousResult) break;
    }

    return result;
};

/**
 * 팝업 닫기
 */
scwin.closeDefectPopup = function () {
    console.log("결함 팝업 닫기");

    // 부모 창의 새로고침 함수 호출 (있다면)
    try {
        var parentWindow = $p.getParentWindow();
        if (parentWindow && parentWindow.scwin && typeof parentWindow.scwin.refreshDefectList === 'function') {
            parentWindow.scwin.refreshDefectList();
        } else if (parentWindow && parentWindow.scwin && typeof parentWindow.scwin.loadDefectList === 'function') {
            parentWindow.scwin.loadDefectList();
        }
    } catch (e) {
        console.log("부모 창 새로고침 호출 실패:", e);
    }

    $p.closePopup();
};

